import math


class DiscreteStateModel:
    def __init__(self, states, symbols, transition, emission, initial):
        self._states = self._distinct(states, "states")
        self._symbols = self._distinct(symbols, "symbols")
        n, m = len(self._states), len(self._symbols)
        self._transition = self._matrix(transition, n, n, "transition")
        self._emission = self._matrix(emission, n, m, "emission")
        self._initial = self._row(initial, n, "initial")
        self._symbol_index = {value: i for i, value in enumerate(self._symbols)}

    @staticmethod
    def _distinct(values, name):
        try:
            result = list(values)
        except TypeError:
            raise TypeError(f"{name} must be a sequence") from None
        if not result:
            raise ValueError(f"{name} must not be empty")
        try:
            if len(set(result)) != len(result):
                raise ValueError(f"{name} must be distinct")
        except TypeError:
            raise TypeError(f"{name} values must be hashable") from None
        return tuple(result)

    @staticmethod
    def _row(values, size, name):
        try:
            row = list(values)
        except TypeError:
            raise TypeError(f"{name} must be a sequence") from None
        if len(row) != size:
            raise ValueError(f"{name} has the wrong size")
        for value in row:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise TypeError(f"{name} must contain numbers")
            if not math.isfinite(value) or value < 0:
                raise ValueError(f"{name} contains an invalid probability")
        if not math.isclose(sum(row), 1.0, abs_tol=1e-9, rel_tol=0.0):
            raise ValueError(f"{name} must sum to one")
        return tuple(float(value) for value in row)

    @classmethod
    def _matrix(cls, values, rows, columns, name):
        try:
            matrix = list(values)
        except TypeError:
            raise TypeError(f"{name} must be a matrix") from None
        if len(matrix) != rows:
            raise ValueError(f"{name} has the wrong row count")
        return tuple(cls._row(row, columns, name) for row in matrix)

    def _observations(self, observations):
        try:
            values = list(observations)
        except TypeError:
            raise TypeError("observations must be iterable") from None
        result = []
        for value in values:
            try:
                result.append(self._symbol_index[value])
            except (KeyError, TypeError):
                raise ValueError(f"unknown symbol: {value!r}") from None
        return result

    def forward(self, observations):
        obs = self._observations(observations)
        if not obs:
            return 1.0
        alpha = [self._initial[i] * self._emission[i][obs[0]] for i in range(len(self._states))]
        for symbol in obs[1:]:
            alpha = [self._emission[j][symbol] * sum(alpha[i] * self._transition[i][j] for i in range(len(alpha))) for j in range(len(alpha))]
        return sum(alpha)

    def backward(self, observations):
        obs = self._observations(observations)
        if not obs:
            return 1.0
        beta = [1.0] * len(self._states)
        for symbol in reversed(obs[:-1]):
            beta = [sum(self._transition[i][j] * self._emission[j][symbol] * beta[j] for j in range(len(beta))) for i in range(len(beta))]
        return sum(self._initial[i] * self._emission[i][obs[0]] * beta[i] for i in range(len(beta)))

